import { headers } from 'next/headers'

type Analytics = { views: number; visits: number }
type Notification = { id: number; message: string }
type Settings = { theme: string; timezone: string }

// Good example: parallel data fetching (mirrors getParallelData in page.tsx)
async function getDashboardData(
  baseUrl: string
): Promise<{
  analytics: Analytics
  notifications: Notification[]
  settings: Settings
}> {
  try {
    const [analytics, notifications, settings] = await Promise.all([
      fetch(`${baseUrl}/api/analytics`).then((r) => r.json()),
      fetch(`${baseUrl}/api/notifications`).then((r) => r.json()),
      fetch(`${baseUrl}/api/settings`).then((r) => r.json()),
    ])

    return { analytics, notifications, settings }
  } catch {
    // Return mock data for build time
    return {
      analytics: { views: 1000, visits: 500 },
      notifications: [{ id: 1, message: 'Welcome back' }],
      settings: { theme: 'light', timezone: 'UTC' },
    }
  }
}

export default async function Dashboard() {
  const head = await headers()
  const host = head.get('host') ?? 'localhost:3000'
  const proto = head.get('x-forwarded-proto') ?? 'http'
  const { analytics, notifications, settings } = await getDashboardData(
    `${proto}://${host}`
  )

  return (
    <div>
      <h2>Dashboard Content</h2>
      <p>Views: {analytics.views}</p>
      <p>Visits: {analytics.visits}</p>

      <h3>Notifications</h3>
      <ul>
        {notifications.map((n) => (
          <li key={n.id}>{n.message}</li>
        ))}
      </ul>

      <h3>Settings</h3>
      <p>Theme: {settings.theme}</p>
      <p>Timezone: {settings.timezone}</p>
    </div>
  )
}

